/**
 * 通道/运维工具组（P7 由 src/index.ts 迁出：1172-1677，零语义改）。
 * kitty_drv / kitty_ce / kitty_status / kitty_x64dbg / kitty_pchain / kitty_dbg / kitty_sym。
 */
import { appendFileSync, existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import {
  bridgeCall, breaker, channel, dbgExePath, ensureDrivers, ensureHost, hostPid,
  hostState, lastCrashSignature, logHostIncident, recoverAux, resetEnsureCache, runX64dbg,
  scQueryState, sleep, toolScriptOf, filterEntries, readImage, waitAndCollect, NO_RETRY_OPS,
  DRV_MAIN, DRV_AUX,
} from '../host-utils.js'
import { callText, TIMEOUT_REPLY, type Channel } from '../bridge.js'
import { knownOpPrefix } from '../ops-catalog.js'
import { pchain } from '../pchain-snippet.js'
import { formatEntries, parseExports, parseImports } from '../sym.js'
import { parsePE } from '../patch.js'
import { getShieldReverseReceipt } from '../shield-reverse.js'
import { getPojiaReverseReceipt } from '../pojia-reverse.js'
import { sessionRoot } from '../session-shards.js'
import type { Ctx, ToolDeps } from './deps.js'

export function registerChannelTools(ctx: Ctx, deps: ToolDeps): void {
  const { defineTool } = deps
  const { live, syncLive, drvGuard } = deps

  /* ---------------- 驱动工具：初始化 / 状态 ---------------- */
  ctx.effect(() => ctx.tools.register(defineTool({
    name: 'kitty_drv',
    description: '驱动+宿主守护：ensure=确保双驱已加载（Private_Access→mhtglyts，带重试）；status=只读状态；' +
      'host=宿主看门狗（KittyCE 消失/桥无响应 → 单实例重拉 + 等 PING + SYNC_ARCHIVE 归一化 + 事故日志）；' +
      'recover=修复卡 STOP_PENDING 的辅助驱（关宿主→落定→重启驱，可选 hostStart 重拉宿主）；force=忽略缓存',
    parameters: {
      action: { type: 'string', description: 'ensure（默认）| status | recover | host | storm' },
      force: { type: 'boolean', description: 'ensure 时忽略 15s 成功缓存' },
      hostStart: { type: 'boolean', description: 'recover/host 时重拉宿主（默认 true；host 动作下 restart=false 只探不拉）' },
      reset_breaker: { type: 'boolean', description: 'host 动作：复位看门狗熔断（窗口内连续重拉达阈值后需显式复位）' },
      cycles: { type: 'number', description: 'storm 的轮次（默认 20，上限 100）' },
      pid: { type: 'number', description: 'storm 时每轮附带 KM_ATTACH|<pid>（内核态附加，验证非破坏路径）' },
    },
    output: {
      schema: { type: 'string' },
      render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }],
    },
    async execute(args: { action?: string; force?: boolean; hostStart?: boolean; cycles?: number; pid?: number; reset_breaker?: boolean }) {
      const act = (args.action ?? 'ensure').toLowerCase()
      if (act === 'status') {
        return `[drv] ${DRV_MAIN}=${scQueryState(DRV_MAIN)} ${DRV_AUX}=${scQueryState(DRV_AUX)}\n[host] KittyCE=${hostState()}`
      }
      if (act === 'host') {
        const pingBefore = await bridgeCall(live.kittyDir, 'PING', 6000)
        const wanted = hostPid()
        if (args.reset_breaker === true) { breaker.tripped = false; breaker.consecutive = 0; breaker.lastRestartAt = 0; return '[breaker] 已复位（consecutive=0 tripped=false）' }
        const r = await ensureHost(() => bridgeCall(live.kittyDir, 'PING', 6000), args.hostStart !== false, live.timeoutMs + 8000, live.root)
        const archive = r.ok ? await bridgeCall(live.kittyDir, 'SYNC_ARCHIVE', live.timeoutMs) : '（未归一化：宿主未就绪）'
        const stat = r.ok ? await bridgeCall(live.kittyDir, 'SYNC_STAT', live.timeoutMs) : ''
        if (!r.ok || !/Kitty-bridge/.test(pingBefore)) {
          logHostIncident(live.root, r.ok ? 'host-restarted' : 'host-unavailable',
            { pidBefore: wanted, pingBefore, crash: lastCrashSignature(), lines: r.lines })
        }
        return [...r.lines, `SYNC_ARCHIVE → ${archive}`, stat ? `SYNC_STAT → ${stat}` : ''].filter(Boolean).join('\n')
      }
      if (act === 'storm') {
        /* P1-T1.3 宿主压测：连续 PING +（可选）KM_ATTACH，丢失即看门狗自愈并计数；判据=20 次零丢失 */
        const cycles = Math.max(1, Math.min(Number(args.cycles ?? 20), 100))
        const wantPid = Number(args.pid ?? 0)
        const ch = channel(live.kittyDir)
        const lines: string[] = []
        const incidents: Array<Record<string, unknown>> = []
        let lost = 0
        let restarts = 0
        let pidSeen = hostPid()
        const t0 = Date.now()
        for (let i = 1; i <= cycles; i++) {
          const p1 = await ch.call('PING', 6000)
          if (p1.timeout) {
            lost++
            const h = await ensureHost(() => callText(ch, 'PING', 6000), true, 25000, live.root)
            restarts++
            incidents.push({ cycle: i, at: 'ping', ok: h.ok, lines: h.lines })
            lines.push(`cycle ${i}: PING 丢失 → 看门狗 ok=${h.ok}（pid ${pidSeen ?? 'none'} → ${hostPid() ?? 'none'}）`)
            pidSeen = hostPid()
            continue
          }
          if (wantPid) {
            const a = await ch.call(`KM_ATTACH|${wantPid}`, 20000)
            lines.push(`cycle ${i}: PING ${p1.ms}ms · KM_ATTACH → ${a.reply.slice(0, 44)}`)
          } else {
            lines.push(`cycle ${i}: PING ${p1.ms}ms`)
          }
        }
        const stat = await callText(ch, 'SYNC_STAT', live.timeoutMs)
        const alive = await callText(ch, 'PING', 6000)
        const ok = lost === 0 && /Kitty-bridge/.test(alive)
        const receipt = { ts: new Date().toISOString(), cycles, wantPid, lost, restarts, pidSeen, pidNow: hostPid(), ms: Date.now() - t0, alive, incidents }
        try { appendFileSync(join(live.root, 'logs', 'host-storm.jsonl'), JSON.stringify(receipt) + '\n', 'utf8') } catch { /* 忽略 */ }
        return [`[storm] cycles=${cycles} 丢失=${lost} 看门狗重启=${restarts} 判据(${cycles} 次零丢失)=${lost === 0 ? 'PASS' : 'FAIL'} 用时=${Date.now() - t0}ms`,
          ...lines.slice(-12), `SYNC_STAT → ${stat}`, `PING（收尾）→ ${alive}`].join('\n')
      }
      if (act === 'ensure') {
        return ensureDrivers(args.force === true, 3) + `\n[host] KittyCE=${hostState()}`
      }
      if (act === 'recover') {
        const out = recoverAux(args.hostStart === true)
        resetEnsureCache()   // 让下次 ensure 重新判定
        return out
      }
      return `ERR|unknown action: ${args.action}`
    },
  })), '@dsh-external/kitty-toolbox: kitty_drv')

  /* ---------------- 通道 A：KittyCE 文件桥 ---------------- */
  ctx.effect(() => ctx.tools.register(defineTool({
    name: 'kitty_ce',
    description: 'KittyCE 直控（A 通道桥 v0.2.9）：OP 透传，如 PING / R|0x..|dword / S_NEW|dword|123|0x..|0x.. / SYNC_STAT；' +
      'scan/P_BACK 类异步 OP 可用 wait=true 自动等作业落定并取样本；拼错 OP 本地早拒；完整 OP 表见 kitty_ops',
    parameters: {
      op: { type: 'string', required: true, description: '单行桥指令，如 PING 或 S_NEW|dword|123456789|0x1000|0x2000' },
      timeout_ms: { type: 'number', description: '超时毫秒，默认 20000' },
      ops: { type: 'array', items: { type: 'string' }, description: 'BATCH 多指令（逐条 OP；给此项则忽略 op，桥 v0.2.5 一次投递）' },

export interface Channel {
  dir: string
  call: (line: string, timeoutMs?: number) => Promise<BridgeReply>
  /** 多行投递（v0.2.5 BATCH）：lines[0] 为 `BATCH`，其余为逐条 OP */
  callLines: (lines: string[], timeoutMs?: number) => Promise<BridgeReply>
}

export interface ChannelOpts {
  /** 轮询间隔（桥 tick = 100ms；60ms 轮询把平均等待压到 ≈半栅格） */
  pollMs?: number
  /** 投递方式回执（诊断用） */
  onDeliver?: (how: 'rename' | 'overwrite') => void
}

export function makeChannel(kittyDir: string, opts: ChannelOpts = {}): Channel {
  try { mkdirSync(kittyDir, { recursive: true }) } catch { /* 已存在 */ }
  const CMDF = join(kittyDir, 'cmd.txt')
  const REPF = join(kittyDir, 'rep.txt')
  const pollMs = opts.pollMs ?? 60
  const runtime = currentRuntime()
  // Shared with operator scripts; ownership lasts until a delivered command settles.
  const withWriter = async (work: () => Promise<BridgeReply>, timeoutMs: number): Promise<BridgeReply> => {
    const lock = join(kittyDir, 'cmd.lock')
    const started = Date.now()
    let handle: number | undefined
    while (handle === undefined) {
      if (runtime && !runtime.active) return denied('', 'GENERATION-STALE')
      try { handle = openSync(lock, 'wx') } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error
        if (Date.now() - started >= timeoutMs) return denied('', 'BRIDGE-LOCK-TIMEOUT')
        await sleep(pollMs)
      }
    }
    const owner = 'node-' + process.pid + '-' + Math.random().toString(36).slice(2)
    const heartbeat = () => { try { writeSync(handle!, owner + '|' + new Date().toISOString(), 0, 'ascii') } catch { /* Delivery still owns the lock until settled. */ } }
    heartbeat()
    const timer = setInterval(heartbeat, 5000)
    try { return await work() }
    finally {
      clearInterval(timer)
      closeSync(handle)
      try { if (readFileSync(lock, 'ascii').startsWith(owner + '|')) unlinkSync(lock) }
      catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error }
    }
  }

  const deliver = (line: string, seq: string, full?: string): 'rename' | 'overwrite' => {
    const tmp = `${CMDF}.${seq}.tmp`
    const body = full ?? (seq + '|' + line)
    writeFileSync(tmp, body, 'ascii')
    for (let i = 0; i < 12; i++) {
      try { renameSync(tmp, CMDF); opts.onDeliver?.('rename'); return 'rename' } catch { sleepSync(15) }
    }
    try { unlinkSync(tmp) } catch { /* 忽略 */ }
    writeFileSync(CMDF, body, 'ascii')
    opts.onDeliver?.('overwrite')
    return 'overwrite'
  }

  const parse = (raw: string, cmd: string, t0: number): BridgeReply => {
    const reply = raw.trim().slice(0, raw.trim().length)
    const nl = reply.indexOf('\n')
    const head = nl < 0 ? reply : reply.slice(0, nl)
    const parts = head.split('|')
    const code = parts[0] ?? ''
    return {
      cmd, reply, ms: Date.now() - t0, ok: code.toUpperCase() === 'OK', timeout: false,
      code, payload: parts.slice(1).join('|').trim(),
      lines: reply.split('\n').map((s) => s.trim()).filter(Boolean).slice(1),
    }
  }

  const rawCallLines = async (lines: string[], timeoutMs: number): Promise<BridgeReply> => {
    const seq = String(Date.now() * 1000 + Math.floor(Math.random() * 1000))
    const t0 = Date.now()
    const text = lines.length > 1 ? `${seq}|${lines[0]}\n${lines.slice(1).join('\n')}` : `${seq}|${lines[0] ?? ''}`
    deliver(text, seq, text)
    while (Date.now() - t0 < timeoutMs) {
      try {
        if (existsSync(REPF)) {
          const raw = readFileSync(REPF, 'utf8').trim()
          if (raw.startsWith(seq + '|')) return parse(raw.slice(seq.length + 1), lines.join(' ; '), t0)
        }
      } catch { /* 半写：下轮再读 */ }
      await sleep(pollMs)
    }
    return {
      cmd: lines.join(' ; '), reply: TIMEOUT_REPLY, ms: Date.now() - t0, ok: false, timeout: true,
      code: 'TIMEOUT', payload: '', lines: [],
    }
  }

  const rawCall = async (line: string, timeoutMs: number): Promise<BridgeReply> => {
    const seq = String(Date.now() * 1000 + Math.floor(Math.random() * 1000))
    const t0 = Date.now()
    deliver(line, seq)
    while (Date.now() - t0 < timeoutMs) {
      try {
        if (existsSync(REPF)) {
          const raw = readFileSync(REPF, 'utf8').trim()
          if (raw.startsWith(seq + '|')) return parse(raw.slice(seq.length + 1), line, t0)
        }
      } catch { /* 半写：下轮再读 */ }
      await sleep(pollMs)
    }
    return {
      cmd: line, reply: TIMEOUT_REPLY, ms: Date.now() - t0, ok: false, timeout: true,
      code: 'TIMEOUT', payload: '', lines: [],
    }
  }

  return {
    dir: kittyDir,
    call: (line, timeoutMs = 15000) => {
      const error = validateBridgeLine(line)
      return error ? Promise.resolve(denied(line, error)) : serializeBridge(() => withWriter(() => rawCall(line, timeoutMs), timeoutMs))
    },
    callLines: (lines, timeoutMs = 15000) => {
      const error = validateBridgeLines(lines)
      return error ? Promise.resolve(denied(lines?.join(' ; ') ?? '', error)) : serializeBridge(() => withWriter(() => rawCallLines(lines, timeoutMs), timeoutMs))
    },
  }
}

/** 兼容旧调用面：只要文本回包（工具输出用）。 */
export async function callText(ch: Channel, line: string, timeoutMs?: number): Promise<string> {
  const r = await ch.call(line, timeoutMs)
  return r.reply
}

/* ---------------- P0-slowop：分片 + job 化 ----------------
 * 慢 OP（大窗口 S_NEW/P_BACK、大块 R bytes:N、MEMDUMP）统一走分片上限 + JOB_STAT 落定等待。
 * 上限：SCAN_WINDOW_MAX=16MB（桥 window-too-big 口径）· R_BYTES_MAX=4096 · MEMDUMP_MAX=4096。
 * job 化：S_NEW/P_BACK 回包 pending 时不重投原指令（重投按 mode=new 重置），只轮询 JOB_STAT/S_GET。 */
export const SLOWOP_LIMITS = {
  SCAN_WINDOW_MAX: 16 * 1024 * 1024,
  R_BYTES_MAX: 4096,
  MEMDUMP_MAX: 4096,
} as const

/** 解析地址字面量（0x十六进制 / 十进制），失败回 NaN。 */
export function parseAddr(s: string): number {
  const t = (s ?? '').trim()
  if (/^0x[0-9a-f]+$/i.test(t)) return Number.parseInt(t.slice(2), 16)
  if (/^-?\d+$/.test(t)) return Number(t)
  return NaN
}

/** 窗口分片：[start, stop) 按 maxChunk 切分为 ≤maxChunk 的子窗口（十进制数字）。 */
export function splitWindow(start: number, stop: number, maxChunk = SLOWOP_LIMITS.SCAN_WINDOW_MAX): Array<{ start: number; stop: number }> {
  if (!Number.isFinite(start) || !Number.isFinite(stop) || stop <= start) return []

