export async function ensureHost(ping: () => Promise<string>, restart = true, waitMs = 20000, root = ''): Promise<{ ok: boolean; lines: string[] }> {
  const lines: string[] = []
  const before = hostPid()
  lines.push(`[host] before=${before ?? 'not-running'}`)
  const probe = async (): Promise<string> => {
    try { const r = (await ping()).trim(); return /Kitty-bridge/.test(r) ? r.split('|').slice(1).join('|') : 'no-ok' } catch { return 'probe-fail' }
  }
  let first = await probe()
  if (!/v0\.2\./.test(first)) {
    if (!restart) return { ok: false, lines: [...lines, `ping=${first}（restart=false 不重拉）`] }
    /* 熔断闸门：窗口内连续重拉达阈值 → 拒绝自动重启（防重启风暴） */
    if (breaker.tripped) {
      lines.push(`[breaker] OPEN（窗口 ${Math.round(breaker.windowMs / 60000)}min 内连续重拉 ${breaker.consecutive} 次 ≥ ${breaker.max}）→ 已停止自动重启；确认环境后执行 kitty_drv action=host reset_breaker=true 复位`)
      if (root) logHostIncident(root, 'watchdog-circuit-refused', { consecutive: breaker.consecutive })
      return { ok: false, lines }
    }
    const nowB = Date.now()
    breaker.consecutive = (nowB - breaker.lastRestartAt <= breaker.windowMs) ? breaker.consecutive + 1 : 1
    breaker.lastRestartAt = nowB
    lines.push(`[breaker] restart#${breaker.consecutive}/${breaker.max}（窗口内计数）`)
    if (breaker.consecutive >= breaker.max) {
      breaker.tripped = true
      lines.push('[breaker] 阈值达成 → 本次重启后熔断打开（后续需显式复位）')
      if (root) logHostIncident(root, 'watchdog-circuit-open', { consecutive: breaker.consecutive })
    }
    if (!existsSync(hostExePath())) return { ok: false, lines: [...lines, `ping=${first}`, `宿主 exe 不存在：${hostExePath()}（改 hostExe 配置可切别的 CE build）`] }
    lines.push(`[host] ${neutralizePendingCmd()}（重启前中和残留 cmd.txt：防新宿主重放僵死 OP）`)
    killHost()                                    // 清多实例/僵死残留（单实例纪律）
    spawnSync('powershell.exe', ['-NoProfile', '-Command', `Start-Process '${hostExePath()}'`], { encoding: 'utf8', timeout: 20000 })
    lines.push(`[host] restart requested（前序 ping=${first}）`)
    const t0 = Date.now()
    while (Date.now() - t0 < waitMs) {
      await sleep(1200)
      first = await probe()
      if (/v0\.2\./.test(first)) break
    }
  }
  const after = hostPid()
  const ok = /v0\.2\./.test(first)
  lines.push(`[host] after=${after ?? 'not-running'} ping=${first}`)
  hostRuntimeState().hostCache = { at: 0, line: 'unknown' }
  return { ok, lines }
}

/** 事故日志（jsonl）：宿主消失/重启的时间、前后 pid、崩溃签名 */
/** 最近一次 KittyCE 崩溃的 WER/事件签名（事故日志用；读不到就写 no-evidence；非 ASCII 一律转 ?，防 GBK/UTF8 误解出乱码） */
export function lastCrashSignature(minutes = 15): string {
  try {
    /* 注意：PowerShell 默认按 ANSI 输出 → 事件消息里的中文会变乱码；此处输出前先把非 ASCII 全部转 ?。 */
    const ps = `[Console]::OutputEncoding=[System.Text.Encoding]::UTF8; ` +
      `$e=Get-WinEvent -FilterHashtable @{LogName='Application';Id=1000;StartTime=(Get-Date).AddMinutes(-${minutes})} -ErrorAction SilentlyContinue | Where-Object { $_.Message -match 'KittyCE' } | Select-Object -First 1; ` +
      `if($e){ $m=(($e.Message -replace "\`r?\`n",' ') -replace '[^\x20-\x7E]','?'); $m.Substring(0,[Math]::Min(160,$m.Length)) } else { 'no-evidence' }`
    const r = spawnSync('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], { encoding: 'utf8', timeout: 25000 })
    return ((r.stdout ?? '').toString().trim() || 'no-evidence').replace(/\s+/g, ' ')
  } catch { return 'probe-fail' }
}

export function logHostIncident(root: string, note: string, extra: Record<string, unknown> = {}): void {
  try {
    const dir = join(root, 'logs')
    mkdirSync(dir, { recursive: true })
    const rec = { ts: new Date().toISOString(), kind: 'host-incident', note, ...extra }
    appendFileSync(join(dir, 'kitty-host-incidents.jsonl'), JSON.stringify(rec) + '\n', 'utf8')
  } catch { /* 记录失败不影响主流程 */ }
}

/**
 * 高危 OP（超时不许重投）：重投会在新宿主上复现同一次僵死/崩溃。
 * 实测（2026-09-20）：`KM_PW` 卡死 Lua 引擎后，自愈重投把同一条 KM_PW 投给新宿主 → 新宿主二次僵死。
 */
export const NO_RETRY_OPS = new Set(['KM_PW'])

/** 模块级镜像的桥目录（`live.kittyDir` 在 apply 作用域内；看门狗/中和函数是模块级，需要它）。 */


/**
 * 重启前中和待处理 cmd.txt。
 * 宿主启动时会读取残留 cmd.txt 并**重放**其中指令（桥 v0.2.x 行为）——
 * 若残留的是一条已经把旧宿主搞僵死的 OP，新宿主开机即二次僵死。
 * 处置：把 cmd.txt 整体替换成一条无害 `PING`（BATCH 的续行一并丢弃）。
 */
export function neutralizePendingCmd(): string {
  try {
    const f = join(hostRuntimeState().liveKittyDir, 'cmd.txt')
    if (!existsSync(f)) return 'no-cmd-file'
    const raw = readFileSync(f, 'utf8')
    if (!raw.trim()) return 'already-empty'
    const first = raw.split(/\r?\n/)[0] ?? ''
    const op = first.split('|').slice(1).join('|').trim() || first.trim()
    const seq = String(Date.now() * 1000 + Math.floor(Math.random() * 1000))
    writeFileSync(f, `${seq}|PING`, 'ascii')
    return `neutralized(${op.slice(0, 48)})`
  } catch (e) { return `neutralize-fail:${(e as Error)?.message ?? String(e)}` }
}

