{"file_path":"D:\BaiduNetdiskDownload\Local-AI\Local-AI-testarea\pyver.ps1","content":"# pyver.ps1 — 检测本机已安装的 Python 版本并输出
# 覆盖: python / python3 / py -3 启动器 / WindowsApps 占位符
$ErrorActionPreference = 'SilentlyContinue'
Write-Host "=== Python 版本探测 ==="

# 1) 直接命令
foreach ($cmd in @('python','python3')) {
    $c = Get-Command $cmd -ErrorAction SilentlyContinue
    if ($c) {
        $out = & $cmd --version 2>&1 | Select-Object -First 1
        Write-Host ("[{0}] -> {1}" -f $cmd, ($out -join ' '))
    }
}

# 2) py 启动器（列出全部注册解释器）
$py = Get-Command py -ErrorAction SilentlyContinue
if ($py) {
    $list = & py -0: 2>&1
    if ($list) { Write-Host "[py launcher]"; $list | ForEach-Object { Write-Host "  $_" } }
    $v = & py -3 --version 2>&1 | Select-Object -First 1
    if ($v) { Write-Host ("[py -3] -> {0}" -f ($v -join ' ')) }
}

# 3) WindowsApps 占位符识别（无真实解释器时返回商店链接）
$winapp = Get-Command python -ErrorAction SilentlyContinue
if ($winapp) {
    $src = $winapp.Source
    if ($src -match 'WindowsApps') {
        Write-Host "[warn] python 指向 WindowsApps 占位符: $src (可能未装 CPython)"
    }
}

# 4) 常见安装目录扫描
$dirs = @(
  "$env:LOCALAPPDATA\Programs\Python",
  "C:\Python*",
  "$env:ProgramFiles\Python*",
  "$env:LOCALAPPDATA\Microsoft\WindowsApps"
)
foreach ($d in $dirs) {
  Get-ChildItem -Path $d -Filter 'python.exe' -Recurse -Depth 2 -ErrorAction SilentlyContinue |
    ForEach-Object { Write-Host ("[file] {0}" -f $_.FullName) }
}
Write-Host "=== 完成 ==="
"}

